const item = items[0].json;

// =========================
// HELPERS
// =========================
function toIsoFromUnixSeconds(value) {
  if (!value) return new Date().toISOString();
  const ts = Number(value) * 1000;
  return isNaN(ts) ? new Date().toISOString() : new Date(ts).toISOString();
}

function safeString(value) {
  if (value === null || value === undefined) return '';
  return String(value);
}

// =========================
// SOURCE DETECTION
// =========================
const isWebhookAmo = !!item.body;
const isTelegram =
  !!item.update_id ||
  !!item.message ||
  !!item.edited_message;

// =========================
// AMO / WEBHOOK BRANCH
// =========================
if (isWebhookAmo) {
  const body = item.body || {};

  function getAuthor(field) {
    return body[`message[add][0][author.${field}]`] ||
           body[`message[add][0][author][${field}]`] ||
           '';
  }

  const textRaw = body['message[add][0][text]']?.trim() || '';
  const contactId = body['message[add][0][contact_id]'] || '';
  const chatId = body['message[add][0][chat_id]'] || '';
  const talkId = body['message[add][0][talk_id]'] || '';
  const entityId =
    body['message[add][0][entity_id]'] ||
    body['message[add][0][element_id]'] ||
    '';
  const elementType = body['message[add][0][element_type]'] || '';
  const createdAt = body['message[add][0][created_at]'] || '';
  const attachType = body['message[add][0][attachment][type]'] || '';
  const attachLink = body['message[add][0][attachment][link]'] || '';
  const origin = body['message[add][0][origin]'] || '';
  const amoAccount = body['account[subdomain]'] || '';
  const amoAccountId = body['account[id]'] || '';
  const msgType = body['message[add][0][type]'] || '';

  const authorId = getAuthor('id');
  const authorType = getAuthor('type');
  const authorName = getAuthor('name');

  const attachments = [];
  if (attachType || attachLink) {
    attachments.push({
      type: safeString(attachType),
      link: safeString(attachLink),
    });
  }

  const normalizedText = textRaw || (attachType === 'voice' ? '[голос]' : '');

  return [{
    json: {
      platform: 'amocrm',
      channel: origin === 'telegram' ? 'amocrm_telegram' : 'amocrm',
      event_type: msgType === 'incoming' ? 'incoming_message' : 'outgoing_message',
      message_text: textRaw,
      normalized_text: normalizedText,
      contact_external_id: safeString(contactId),
      conversation_external_id: safeString(chatId),
      external_message_id: '',
      lead_external_id: safeString(entityId),
      attachments,
      timestamp: toIsoFromUnixSeconds(createdAt),
      is_new_contact_guess: !chatId && !talkId,
      source_metadata: {
        amo_account: safeString(amoAccount),
        amo_account_id: safeString(amoAccountId),
        talk_id: safeString(talkId),
        element_type: safeString(elementType),
        author_id: safeString(authorId),
        author_type: safeString(authorType),
        author_name: safeString(authorName),
        origin: safeString(origin || 'amocrm'),
        source_type: 'webhook_amocrm',
      },
      raw_payload: body,
    }
  }];
}

// =========================
// TELEGRAM BRANCH
// =========================
if (isTelegram) {
  const update = item;
  const msg = update.message || update.edited_message || null;

  if (!msg) {
    return [{
      json: {
        platform: 'telegram',
        channel: 'telegram_direct',
        event_type: 'unsupported_event',
        message_text: '',
        normalized_text: '',
        contact_external_id: '',
        conversation_external_id: '',
        external_message_id: '',
        lead_external_id: '',
        attachments: [],
        timestamp: new Date().toISOString(),
        is_new_contact_guess: false,
        source_metadata: {
          telegram_update_id: safeString(update.update_id),
          origin: 'telegram',
          source_type: 'telegram_trigger',
        },
        raw_payload: update,
      }
    }];
  }

  const textRaw = msg.text?.trim() || msg.caption?.trim() || '';
  const hasVoice = !!msg.voice;
  const hasAudio = !!msg.audio;
  const hasPhoto = !!msg.photo;
  const hasDocument = !!msg.document;
  const hasVideo = !!msg.video;
  const hasVideoNote = !!msg.video_note;

  const attachments = [];
  if (hasVoice) attachments.push({ type: 'voice', file_id: safeString(msg.voice.file_id) });
  if (hasAudio) attachments.push({ type: 'audio', file_id: safeString(msg.audio.file_id) });
  if (hasPhoto) attachments.push({ type: 'photo' });
  if (hasDocument) attachments.push({ type: 'document', file_id: safeString(msg.document.file_id) });
  if (hasVideo) attachments.push({ type: 'video', file_id: safeString(msg.video.file_id) });
  if (hasVideoNote) attachments.push({ type: 'video_note', file_id: safeString(msg.video_note.file_id) });

  const normalizedText =
    textRaw ||
    (hasVoice ? '[голос]' :
    hasAudio ? '[аудио]' :
    hasPhoto ? '[фото]' :
    hasDocument ? '[документ]' :
    hasVideo ? '[видео]' :
    hasVideoNote ? '[видеосообщение]' : '');

  return [{
    json: {
      platform: 'telegram',
      channel: 'telegram_direct',
      event_type: 'incoming_message',
      message_text: textRaw,
      normalized_text: normalizedText,
      contact_external_id: safeString(msg.from?.id),
      conversation_external_id: safeString(msg.chat?.id),
      external_message_id: safeString(msg.message_id),
      lead_external_id: '',
      attachments,
      timestamp: msg.date
        ? new Date(Number(msg.date) * 1000).toISOString()
        : new Date().toISOString(),
      is_new_contact_guess: false,
      source_metadata: {
        telegram_update_id: safeString(update.update_id),
        telegram_user_id: safeString(msg.from?.id),
        telegram_chat_id: safeString(msg.chat?.id),
        telegram_chat_type: safeString(msg.chat?.type),
        author_name: safeString(msg.from?.first_name),
        author_username: safeString(msg.from?.username),
        language_code: safeString(msg.from?.language_code),
        is_bot: !!msg.from?.is_bot,
        origin: 'telegram',
        source_type: 'telegram_trigger',
      },
      raw_payload: update,
    }
  }];
}

// =========================
// FALLBACK
// =========================
return [{
  json: {
    platform: 'unknown',
    channel: 'unknown',
    event_type: 'unsupported_event',
    message_text: '',
    normalized_text: '',
    contact_external_id: '',
    conversation_external_id: '',
    external_message_id: '',
    lead_external_id: '',
    attachments: [],
    timestamp: new Date().toISOString(),
    is_new_contact_guess: false,
    source_metadata: {
      origin: 'unknown',
      source_type: 'unknown',
    },
    raw_payload: item,
  }
}];

const normalized = $("Нормализовать вход").first().json;

const deal = $("Comandos AmoCRM").isExecuted
  ? $("Comandos AmoCRM").first().json
  : {};

const prepared = $("Prepare Text").isExecuted
  ? $("Prepare Text").first().json
  : {};

// DB IDs берем либо из CRM-ветки, либо из нового Telegram SQL-узла
const db = $("Записать входящее сообщение").isExecuted
  ? $("Записать входящее сообщение").first().json
  : (
      $("Регистрировать лид").isExecuted
        ? $("Регистрировать лид").first().json
        : {}
    );

const finalChannel = normalized.channel || "unknown";

const finalMessageText =
  prepared.text ||
  normalized.message_text ||
  normalized.normalized_text ||
  "";

let replyPayload = {};

if (normalized.platform === "amocrm") {
  replyPayload = {
    chat_id: normalized.conversation_external_id || null,
    talk_id: normalized.source_metadata?.talk_id || null,
    author_id: normalized.source_metadata?.author_id || null,
    element_type: normalized.source_metadata?.element_type || "2",
    entity_id: normalized.lead_external_id || null,
  };
}

if (normalized.platform === "telegram") {
  replyPayload = {
    telegram_chat_id: normalized.conversation_external_id || null,
    telegram_user_id: normalized.contact_external_id || null,
    telegram_message_id: normalized.external_message_id || null,
  };
}

return {
  lead_id: db.lead_id || null,
  conversation_id: db.conversation_id || null,
  message_id: db.message_id || null,
  run_id: db.run_id || null,

  context: {
    platform: normalized.platform || "unknown",
    channel: finalChannel,
    lead_status: "new",
    current_stage: deal.status_id || null,
    active_workflow: "01_Ingress_Channel_Intake",
    needs_human: false,
  },

  input: {
    message_text: finalMessageText,
    raw_text: normalized.message_text || "",
    attachments: normalized.attachments || [],
    lead_profile: {
      name: normalized.source_metadata?.author_name || "Guest",
      external_id: normalized.contact_external_id || null,
      username: normalized.source_metadata?.author_username || null,
    },
  },

  crm_context: {
    deal_id: deal.id || null,
    price: Number(deal.price) || 0,
    pipeline_id: deal.pipeline_id || null,
    subdomain: normalized.source_metadata?.amo_account || null,
    link:
      deal.id && normalized.source_metadata?.amo_account
        ? `https://${normalized.source_metadata.amo_account}.amocrm.ru/leads/detail/${deal.id}`
        : null,
  },

  reply_payload: replyPayload,

  metadata: {
    timestamp: normalized.timestamp || new Date().toISOString(),
    source_workflow: "01_Ingress_Channel_Intake",
    execution_id: $execution.id,
    is_voice: !!(normalized.attachments && normalized.attachments[0]?.type === "voice"),
    source_type: normalized.source_metadata?.source_type || null,
    external_message_id: normalized.external_message_id || null,
  },
};
